app.get('/api/oxygen/invoice-raw/:id', async (req, res) => {
  if (!OXY.key) return res.json({ configured: false });
  const id = req.params.id;
  const out = { id: id, base: OXY.base };
  try {
    const r = await oxyFetch('/invoices/' + encodeURIComponent(id));
    out.status = r.status; out.ok = r.ok;
    const b = (r.body && (r.body.data || r.body)) || {};
    out.keys = (b && typeof b === 'object') ? Object.keys(b) : [];
    const pick = {};
    ['id','number','sequence','document_type','mydata','pdf','pdf_url','public_url','permalink','url','download_url','file','file_url','qr_url','qrUrl','uid','mark','status'].forEach(function(k){ if (b && b[k] !== undefined) pick[k] = b[k]; });
    out.fields = pick;
  } catch (e) { out.err = String((e && e.message) || e); }
  const B = OXY.base.replace(/\/+$/, '');
  const probe = async function(label, url, headers) {
    try { const r = await fetch(url, { headers: Object.assign({ Authorization: 'Bearer ' + OXY.key }, headers || {}) }); out[label] = { status: r.status, contentType: r.headers.get('content-type'), len: r.headers.get('content-length') }; }
    catch (e) { out[label] = { err: String((e && e.message) || e) }; }
  };
  await probe('pdf_endpoint', B + '/invoices/' + encodeURIComponent(id) + '/pdf');
  await probe('accept_pdf', B + '/invoices/' + encodeURIComponent(id), { Accept: 'application/pdf' });
  await probe('print_endpoint', B + '/invoices/' + encodeURIComponent(id) + '/print');
  res.json(out);
});

